// Nur neue Einträge weitergeben und Ruhezeiten einhalten.
// Bereits gesendete Links merkt sich der Workflow in den Static Data
// (funktioniert nur bei aktivem Workflow, nicht bei manueller Ausführung).
const RUHE_VON = 22; // ab 22 Uhr nichts senden
const RUHE_BIS = 7;  // bis 7 Uhr nichts senden
const MAX_PRO_LAUF = 3;

const stunde = Number(new Date().toLocaleString('de-DE', { hour: '2-digit', hour12: false, timeZone: 'Europe/Berlin' }));
if (stunde >= RUHE_VON || stunde < RUHE_BIS) {
  return [];
}

const speicher = $getWorkflowStaticData('global');
const gesendet = new Set(speicher.gesendet || []);

const neu = [];
for (const item of $input.all()) {
  const link = item.json.link;
  if (!link || gesendet.has(link)) continue;
  gesendet.add(link);
  neu.push(item);
  if (neu.length >= MAX_PRO_LAUF) break;
}
// Liste begrenzen, damit die Static Data nicht endlos wächst
speicher.gesendet = [...gesendet].slice(-500);

return neu.map(item => ({
  json: { text: `📰 ${item.json.title}\n\n${item.json.link}` },
}));
